//! Plain-language definitions of the words the demos use.
//!
//! Explanations mark a term as `[[term]]`; the panel then underlines it and shows the
//! definition on hover. A test makes sure every marked term has an entry here.

pub static GLOSSARY: &[(&str, &str)] = &[
    ("access address", "A 32-bit number at the start of every Bluetooth LE packet that says which conversation the packet belongs to. All advertising packets share one fixed value."),
    ("AD structure", "One labelled item inside advertising data: a length byte, a type byte, then the data (a name, a flag, a mesh message ...)."),
    ("ADC", "Analog-to-digital converter: the part of a microcontroller that measures a voltage and turns it into a number."),
    ("advertising", "Bluetooth LE's way of broadcasting: a device repeatedly sends a short packet on three fixed channels, for anyone listening."),
    ("AES", "The Advanced Encryption Standard: a recipe that scrambles a 16-byte block with a key so that only someone with the same key can unscramble it."),
    ("aliasing", "A fast signal that is sampled too rarely shows up in the samples as a slower signal that is not really there."),
    ("amplitude", "How strong a wave is: the height of its peaks."),
    ("antenna", "A piece of metal shaped so that electric current in it sends out radio waves, and radio waves passing by cause current in it."),
    ("AppKey", "Application key: the secret that encrypts what a mesh message means (for example \"lamp on\"). Relays do not need it."),
    ("ATT", "Attribute Protocol: the small request-and-answer packets with which a Bluetooth LE client reads and writes a server's attributes."),
    ("attribute", "One row in a Bluetooth device's table of data: a number (the handle), a type, and a value."),
    ("average current", "The steady current that would drain a battery just as fast as the real, constantly changing current does."),
    ("band-pass filter", "A filter that lets through only changes within a range of speeds (frequencies): slower ones and faster ones are both held back."),
    ("bandwidth", "How wide a range of frequencies a signal occupies, or a receiver lets in."),
    ("baseband", "A signal described relative to its carrier. Zero means \"exactly the carrier frequency\"."),
    ("beat frequency", "The slow tone you get when two nearby frequencies are mixed: its frequency is the difference between the two."),
    ("bit", "The smallest piece of information: a 0 or a 1."),
    ("Bluetooth Mesh", "A way of connecting many Bluetooth devices so that messages hop from device to device across a whole building, instead of going only between two devices."),
    ("bootloader", "A small program that runs first after every reset, checks which firmware is in flash, and starts it. It can also replace the firmware."),
    ("bounce", "A mechanical switch does not close cleanly: the contacts chatter open and closed for a few milliseconds."),
    ("buck converter", "A circuit that makes a lower DC voltage from a higher one by switching rapidly and smoothing the result with a coil and a capacitor, wasting very little power."),
    ("byte", "Eight bits. Usually written as two hexadecimal digits, such as 4A."),
    ("CAN", "Controller area network: a two-wire bus on which any device may start a message, and the message with the lowest identifier automatically goes first."),
    ("carrier", "A steady radio wave of one fixed frequency. On its own it carries no information; a transmitter changes it slightly to send data."),
    ("CFAR", "Constant false alarm rate: a radar detection threshold that is set from the measured background around each cell, so that noise is mistaken for a target equally rarely everywhere."),
    ("channel", "One of the fixed frequencies a radio system may use. Bluetooth LE has 40, each 2 MHz apart."),
    ("checksum", "A short number calculated from a block of data. If the data changes, the number no longer matches, so damage is noticed."),
    ("chirp", "A signal whose frequency sweeps steadily from low to high. FMCW radars send one chirp after another."),
    ("clock", "A steady train of electrical pulses that paces everything inside a microcontroller: the processor does one small step per pulse."),
    ("clutter", "Echoes from things that are not of interest, such as the ground, rain or walls, which raise the background a radar must look through."),
    ("comparator", "A circuit that compares two voltages and answers with a single bit: which of the two is higher."),
    ("compare value", "A number a timer keeps comparing its counter against. When they match, something happens - for PWM, the output pin switches."),
    ("connection event", "One short meeting of two connected Bluetooth LE devices: they wake up on an agreed channel at an agreed time, exchange packets, and sleep again."),
    ("connection interval", "The time from the start of one connection event to the start of the next."),
    ("cooperative thread", "In Zephyr, a thread with a negative priority: once it runs, no other thread can take the processor from it until it sleeps or waits of its own accord."),
    ("counter", "The part of a timer that counts clock ticks: 0, 1, 2 ... up to a limit, then starts again."),
    ("CRC", "Cyclic redundancy check: a few extra bits computed from the data and sent along with it. The receiver computes them again; if they differ, the packet was damaged."),
    ("crystal", "A small piece of quartz that vibrates at a very exact frequency. Used as the heart of an accurate oscillator."),
    ("DALI", "Digital addressable lighting interface: a slow two-wire bus that connects the lamps, sensors and controls of a building's lighting."),
    ("dB", "Decibel: a way of writing ratios. +10 dB is ten times the power, +3 dB about double, -20 dB a hundredth."),
    ("dBi", "Antenna gain in decibels compared with an imaginary antenna that radiates equally in all directions. A half-wave dipole has 2.15 dBi."),
    ("dBm", "Power in decibels relative to one milliwatt: 0 dBm is 1 mW, +10 dBm is 10 mW, -10 dBm is 0.1 mW, -90 dBm is a millionth of a millionth of 1 mW."),
    ("deadline", "The latest moment by which a job must be finished to be of use. For a periodic task it is usually the moment its next job is due."),
    ("debounce", "Ignoring the chatter of a switch so that one press counts as one press."),
    ("deviation", "How far a frequency-modulated transmitter moves away from its centre frequency to signal a bit."),
    ("devicetree", "A text file that describes a board's hardware to the Zephyr build: which devices exist, on which pins and buses."),
    ("dipole", "The simplest antenna: a straight wire, usually half a wavelength long, fed in the middle."),
    ("DMA", "Direct memory access: hardware that copies data between a peripheral and memory by itself, without the processor handling each byte."),
    ("Doppler shift", "The change in frequency of a wave reflected by something that moves: higher if it approaches, lower if it moves away."),
    ("driver", "A piece of software that knows how to operate one particular piece of hardware and offers it to the rest of the firmware through a standard set of functions."),
    ("duty cycle", "The share of time a signal is high. 25 % means high for a quarter of each period."),
    ("element", "In Bluetooth Mesh, one independently addressable part of a device, for example one lamp in a fitting with two lamps. Each element has its own unicast address."),
    ("false alarm", "A detection reported where there is nothing, caused by noise that happened to cross the threshold."),
    ("FFT", "Fast Fourier transform: a calculation that takes a stretch of signal and tells you how much of each frequency is in it."),
    ("fixed-point", "Storing a number with a fractional part as a whole number of small fixed steps, so that integer arithmetic can be used."),
    ("flash", "The memory in which a microcontroller keeps its program. It keeps its contents without power, but is slow to write."),
    ("flooding", "Delivering a message by having every relay repeat it, so it spreads through the network like a rumour."),
    ("frequency", "How many times per second a wave repeats. Measured in hertz (Hz)."),
    ("friend node", "In Bluetooth Mesh, a node with a mains supply that stores messages for a sleeping low power node until it asks for them."),
    ("GATT", "Generic Attribute Profile: the way a connected Bluetooth LE device offers its data, as a table of services, characteristics and values that the other side reads and writes."),
    ("GFSK", "Gaussian frequency-shift keying: sending bits by nudging the carrier frequency up or down, with the changes smoothed so the signal stays narrow. Used by Bluetooth LE."),
    ("GPIO", "General-purpose input/output: a pin of a microcontroller that software can read or drive high or low."),
    ("handler", "The function a microcontroller runs when an interrupt arrives. Also called an interrupt service routine (ISR)."),
    ("HCI", "Host controller interface: the standard set of commands and events between the two halves of a Bluetooth stack, the host and the controller."),
    ("heap", "The part of RAM from which a program can request memory while it runs, in pieces of any size."),
    ("hertz", "The unit of frequency: repetitions per second. kHz is thousands, MHz millions, GHz billions."),
    ("hop", "In a connection: moving to a different channel for the next meeting. In a mesh: one step from one node to a neighbour."),
    ("I2C", "Inter-integrated circuit bus: two wires, clock and data, shared by many chips, each of which is called by its address."),
    ("inductor", "A coil of wire. It resists changes of the current through it, storing energy in its magnetic field while the current rises and giving it back while it falls."),
    ("interference", "What happens where waves meet: they add. Peaks on peaks give more, peaks on troughs cancel."),
    ("interrupt", "A signal that makes the processor stop what it is doing, run a short handler, and then carry on where it left off."),
    ("IQ", "Two numbers per sample (in-phase and quadrature) that together give a signal's strength and phase. Think of them as the x and y of an arrow."),
    ("IV index", "A 32-bit counter shared by a whole mesh network that goes into every encryption, so sequence numbers can be reused after it is raised."),
    ("Kconfig", "Zephyr's system of named switches (all starting with CONFIG_) that decide which features are built into the firmware."),
    ("key", "A secret number used to encrypt and decrypt data. Whoever has the key can read the data."),
    ("latency", "The delay between something being requested and it happening."),
    ("LFSR", "Linear-feedback shift register: a row of bits that shifts along and feeds some of them back in. It produces a fixed scrambled-looking sequence."),
    ("link layer", "The part of Bluetooth LE that decides exactly when and on which channel the radio sends and listens, and repeats packets that were not acknowledged."),
    ("lock", "A marker that only one task can hold at a time, used to keep two tasks from changing the same data at once. Also called a mutex."),
    ("logic analyzer", "A measuring tool that records whether digital signals are high or low, many times per second, and can decode the recording into bytes."),
    ("low power node", "A battery-powered Bluetooth Mesh node that sleeps most of the time and collects its messages from a friend node now and then."),
    ("low-pass filter", "Something that lets slow changes of a signal through and holds fast changes back."),
    ("LSB", "Least significant bit: the bit worth 1, the rightmost when a number is written out."),
    ("mAh", "Milliampere-hour: the unit for how much charge a battery holds. 1 mAh is a current of 1 mA flowing for one hour."),
    ("main loop", "The ordinary code of a firmware that runs round and round when no interrupt handler is running."),
    ("message cache", "A short list a mesh node keeps of messages it has already seen, so it does not act on or relay the same message twice."),
    ("message queue", "A fixed number of slots through which threads and interrupt handlers pass small data items to each other, first in, first out."),
    ("MIC", "Message integrity check: a few bytes that prove a message was made with the right key and has not been changed."),
    ("modulation", "Changing a carrier - its strength, frequency or phase - so that it carries information."),
    ("NetKey", "Network key: the secret that every node of a mesh network shares. It hides and protects who is talking to whom."),
    ("NID", "A 7-bit number derived from the NetKey and sent unencrypted, so a node can quickly tell which key a packet needs."),
    ("noise", "Random unwanted signal that is always present. The weaker the wanted signal, the more the noise spoils it."),
    ("nonce", "A number used once: mixed into each encryption so that the same message never produces the same scrambled bytes twice."),
    ("NVIC", "Nested vectored interrupt controller: the part of an ARM Cortex-M processor that decides which interrupt runs and when."),
    ("obfuscation", "Hiding fields of a mesh packet (who sent it, its sequence number) so an eavesdropper cannot track devices."),
    ("op-amp", "Operational amplifier: a chip that amplifies the difference between its two inputs enormously. With a few resistors around it, it becomes an amplifier with an exact, chosen gain."),
    ("oscillator", "A circuit that produces a steady train of pulses: the source of a clock."),
    ("packet", "One self-contained burst of data sent over the air."),
    ("pairing", "The procedure in which two Bluetooth devices that have never met agree on a secret key, so that they can encrypt their connection."),
    ("PDU", "Protocol data unit: the meaningful content of a packet at one layer, without the wrapping the lower layers add."),
    ("pending", "An interrupt that has been requested but whose handler has not started yet."),
    ("period", "The time one repetition of a wave, a signal or a regularly repeated job takes. It is 1 divided by the frequency."),
    ("phase", "Where in its cycle a wave is, written as an angle from 0 to 360 degrees."),
    ("PIR", "Passive infrared sensor: a motion detector that notices the change in infrared (heat) radiation when a warm body moves through its field of view. It sends nothing out itself."),
    ("PLL", "Phase-locked loop: a circuit that makes a higher frequency out of a lower one, exactly a chosen number of times as high."),
    ("preamble", "The alternating bits at the very start of a packet that let the receiver settle and find the bit timing."),
    ("preemptible thread", "In Zephyr, a thread with a priority of zero or above: a more urgent thread can take the processor from it at any moment."),
    ("preemption", "Something more urgent cutting into something less urgent that is already running: an interrupt into a handler, or one task into another."),
    ("prescaler", "A divider in front of a timer that slows the clock down, so the counter ticks less often."),
    ("presence detection", "Telling whether someone is in a room even when they sit still, for example by measuring the tiny movements of breathing."),
    ("priority", "How urgent an interrupt or a task is. For interrupts on ARM Cortex-M a lower number means more urgent."),
    ("provisioning", "In Bluetooth Mesh, the procedure by which a new device is given the network's key and its own address, and so becomes part of the network."),
    ("pull-up", "A resistor that gently holds a pin high, so the pin reads 1 until something (like a pressed button) pulls it low."),
    ("PWM", "Pulse-width modulation: switching a pin on and off quickly and varying the share of on-time, to dim a lamp or set a motor's speed."),
    ("range resolution", "The smallest distance between two objects at which a radar still sees two separate objects."),
    ("reference voltage", "The known, steady voltage an ADC compares its input with. It is the top of the measuring range."),
    ("relay", "A mesh node that repeats messages it hears, so they reach nodes that are out of the sender's range."),
    ("reload value", "The number at which a timer's counter starts over. It sets how long one period lasts."),
    ("replay attack", "Recording a genuine message and sending the same bytes again later, hoping the receiver acts on it a second time."),
    ("resolution", "How finely something is measured. For an ADC: the number of bits in its result - N bits give 2 to the power N steps."),
    ("ring buffer", "A fixed block of memory used as a queue: a write position and a read position chase each other round it, wrapping from the end back to the start."),
    ("RS-485", "An electrical standard for sending data over a twisted pair of wires as the difference between them, which makes it robust over long, noisy cables."),
    ("RSSI", "Received signal strength indicator: how strong a packet arrived."),
    ("RTOS", "Real-time operating system: a small piece of software that lets firmware be written as several tasks and decides which of them runs when."),
    ("sample", "One measurement of a signal at one instant."),
    ("scanning", "Listening on the advertising channels for packets."),
    ("scheduler", "The part of an RTOS that decides which task gets the processor at each moment."),
    ("segment", "One piece of a message that was too long for a single packet and was cut up. Each piece carries its position, so the receiver can put them back together."),
    ("semaphore", "A counter that threads and interrupt handlers use to signal each other: giving adds one, taking subtracts one or waits while it is zero."),
    ("sensitivity", "The weakest signal a radio receiver can still decode reliably, usually given in dBm."),
    ("sequence number", "A counter a mesh node raises for every message it sends. Receivers refuse numbers they have already seen."),
    ("sleep mode", "A state in which a microcontroller switches off parts of itself to save power until something wakes it up."),
    ("spectrum", "A picture of a signal sorted by frequency: how much of each frequency it contains."),
    ("SPI", "Serial peripheral interface: a fast connection between chips with a clock wire, one data wire in each direction, and a select wire per chip."),
    ("stack", "An area of memory where the processor notes what it was doing so it can return to it later."),
    ("stack pointer", "The processor register that holds the address where the stack currently ends."),
    ("state", "The one situation a device is in right now, out of a fixed list of possible ones, such as off, on or warning."),
    ("state machine", "A way of writing behaviour: a list of states, and for each state what every possible event does - which state follows and what action is taken."),
    ("task", "A piece of firmware with a job of its own, written as if it had the processor to itself. An RTOS switches between tasks."),
    ("thread", "Zephyr's word for a task: a piece of firmware with a job and a stack of its own, which the scheduler runs in turn with the others."),
    ("time slice", "A fixed stretch of time after which a running thread must let another thread of the same priority have a turn."),
    ("timer", "A counter inside the microcontroller driven by a clock. The basis of delays, PWM, and measuring time."),
    ("TTL", "Time to live: a number in a mesh packet that every relay lowers by one. When it runs out, the packet is not relayed any further."),
    ("UART", "Universal asynchronous receiver/transmitter: the hardware behind a serial port, which sends each byte as a start bit, eight data bits and a stop bit on one wire, without a clock wire."),
    ("USB", "Universal serial bus: the connection between a computer and its devices, in which the computer (the host) asks each device in turn and a device only speaks when asked."),
    ("wake-up time", "How long a microcontroller needs to get from a sleep mode back to running code."),
    ("watchdog", "A timer inside the microcontroller that resets the chip unless the firmware restarts it in time. It rescues a device whose firmware has got stuck."),
    ("wavelength", "The distance from one wave peak to the next. Higher frequency means shorter wavelength."),
    ("whitening", "Scrambling the bits of a packet with a fixed pattern so there are no long runs of identical bits, which radios handle badly."),
    ("workqueue", "A thread that runs short jobs handed to it by other code, one after the other, in the order they were submitted."),
    ("yield", "A thread stepping to the back of the queue so that others of the same priority can run. It can do so itself, or the scheduler does it at the end of a time slice."),
    ("Zephyr", "An open-source real-time operating system for microcontrollers, developed as a Linux Foundation project and supported by many chip makers."),
];

/// Find a definition. Case-insensitive, and forgiving about a plural "s".
pub fn lookup(term: &str) -> Option<&'static str> {
    let t = term.trim().to_lowercase();
    let find = |t: &str| GLOSSARY.iter().find(|(k, _)| k.to_lowercase() == t).map(|(_, d)| *d);
    find(&t).or_else(|| t.strip_suffix('s').and_then(find)).or_else(|| t.strip_suffix("es").and_then(find))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_is_forgiving() {
        assert!(lookup("CRC").is_some());
        assert!(lookup("crc").is_some());
        assert!(lookup("packets").is_some());
        assert!(lookup("Carrier").is_some());
        assert!(lookup("no such thing").is_none());
    }

    #[test]
    fn sorted_and_unique() {
        for w in GLOSSARY.windows(2) {
            assert!(w[0].0.to_lowercase() < w[1].0.to_lowercase(), "{} / {}", w[0].0, w[1].0);
        }
    }
}
